        and c.summary like concat('%', #{summary}, '%')


        and date_format(c.create_time, '%Y%m%d') >= date_format(#{params.beginTime}, '%Y%m%d')


        and date_format(c.create_time, '%Y%m%d') <= date_format(#{params.endTime}, '%Y%m%d')


order by
    case when c.status in ('4','5') then 1 else 0 end,
    case c.warn_level when '红灯' then 0 when '黄灯' then 1 else 2 end,
    c.deadline asc,
    c.create_time desc


where c.del_flag = '0'
  and c.person_id = #{personId}

  and c.clue_id != #{excludeClueId}

  and c.create_time >= date_sub(curdate(), interval #{days} day)
order by c.create_time desc

